    "batchImport.guide.fundSubtypeSource": "基金模板里，`fundSubtype` 和 `source` 是显式字段，不再只靠备注判断。预览阶段会按基金账户已有设置补全确认天数、确认日期和手续费，不再为了预览额外查询净值。定投部分成功并退回余额时，建议写成一条 `buy + regular_invest` 和一条 `refund + regular_invest_refund`。",
    "batchImport.guide.normalBill": "账单记录按中文字段导入：模板列尽量直接对应入库字段语义。`收支大类` 对应记录类型，`金额` 对应金额，`流出/流入` 优先表达账户侧方向，`分类` 对应分类，`标签` 对应标签关联，`备注` 对应备注。`流出/流入` 是推荐列，不是必填；只有 `金额` 一列时，系统按金额正负、收支大类和还款/退款关键词兜底判断。转账时，`账户` 可按当前账户视角填写，`对向账户` 填另一侧账户；信用卡还款也按转账处理，可把信用卡放在账户列并把还款额填入流入。旧文件如果仍使用“类型/原始类型”或旧信用卡模板的 `cardAccount/type/merchant` 列，系统也继续兼容识别。",
