    "batchImport.template.normal.title": "账单记录导入",
    "batchImport.template.normal.description": "一个入口导入普通账单或信用卡账单，系统会在读取文件时自动判断模式。普通账单逐行识别账户；信用卡账单统一确认信用卡，还款行另行识别付款账户。",
    "batchImport.template.normal.status": "可上传导入",
    "batchImport.template.normal.field.date": "写入交易日期，格式 YYYY-MM-DD，对应库里的 date。",
    "batchImport.template.normal.field.postedAt": "支出记录可填实际入账日期，格式 YYYY-MM-DD，对应库里的 postedAt；留空时按交易日期处理。",
    "batchImport.template.normal.field.majorType": "写入记录大类，对应库里的 type；填写 支出、收入、转账、投资。信用卡还款也填写 转账，系统按账户方向识别，不需要在分类里写信用卡还款。",
    "batchImport.template.normal.field.amount": "写入记录金额，对应库里的 amount；模板建议填正数并用“流出/流入”表达方向。若原文件只有金额列，系统会按金额正负、收支大类和还款/退款关键词推断。",
    "batchImport.template.normal.field.outflow": "账户侧资金减少时填写，例如消费、转出、取现。",
    "batchImport.template.normal.field.inflow": "账户侧资金增加时填写，例如收入、信用卡还款、退款、退货、冲正。",
    "batchImport.template.normal.field.account": "对应主账户。支出/收入写发生账户；转账可写当前视角账户。信用卡消费、退款、还款可统一写信用卡账户，再用流入/流出表达方向。",
    "batchImport.template.normal.field.counterAccount": "对应转账另一侧账户。信用卡还款若账户列是信用卡，这里写付款账户；若账户列是付款账户，这里写信用卡账户。",
    "batchImport.template.normal.field.category": "对应分类字段。支出、收入建议填写，例如餐饮、利息收入、利息支出、工资。",
    "batchImport.template.normal.field.institution": "对应收支机构，仅限银行或第三方支付机构。",
    "batchImport.template.normal.field.tags": "对应标签关联。可填一个或多个标签，使用中文逗号或英文逗号分隔。",
    "batchImport.template.normal.field.remark": "对应主备注，写入 note。",
    "batchImport.template.fund.title": "基金记录模板",
    "batchImport.template.fund.description": "用于基金买入、卖出、分红、退回、手续费、净值、份额等明细。导入预览会自动补全净值、手续费、份额和确认日期；其中资金账户、基金账户、fundSubtype 和 source 都需要明确区分。",
    "batchImport.template.pending": "模板已提供，导入待专用流程",
    "batchImport.template.fund.field.date": "交易日期，格式 YYYY-MM-DD。",
    "batchImport.template.fund.field.fundSubtype": "基金动作。常用值：buy（买入/申购）、redeem（赎回）、dividend_cash（现金分红）、dividend_reinvest（分红再投）、refund（资金退回，导入时会兼容写入退回记录）。",
    "batchImport.template.fund.field.source": "来源语义。常用值：manual（手工）、regular_invest（定投买入）、regular_invest_refund（定投资金退回）。如果是定投 200 成功 100 退回 100，要拆成一条 buy + regular_invest 和一条 refund + regular_invest_refund。",
    "batchImport.template.fund.field.cashAccount": "资金账户名称。买入、定投买入、退回资金、赎回到账等涉及现金流时建议填写；后续正式导入时会据此匹配资金账户。",
    "batchImport.template.fund.field.fundAccount": "基金账户名称。用于区分不同基金账户；如果有多个基金账户，这一列必须明确填写，不能只靠基金代码推断。",
    "batchImport.template.fund.field.fundCode": "基金代码，后续用于净值和持仓联动。",
    "batchImport.template.fund.field.fundName": "基金名称，可用于补全显示。",
    "batchImport.template.fund.field.amount": "发生金额，填正数即可；具体方向由 fundSubtype 决定，不靠正负号判断。",
    "batchImport.template.fund.field.units": "确认份额。买入、赎回建议填写；资金退回通常留空。",
    "batchImport.template.fund.field.nav": "成交净值。买入、赎回建议填写；资金退回通常留空。",
