    "viewImport.notesIntroNormal": "模板页第 1 行是稳定字段键名；导入时按字段键名识别。备注字段固定放在最后。",
    "viewImport.notesRecognitionNormal": "系统只识别有明确表头和收支方向的字段；不能确定含义时会在预览里报错或警告，不会把字段强行改作其他用途。",
    "viewImport.notesDate": "必填。写交易日期，推荐 YYYY-MM-DD；也兼容常见 Excel 日期。",
