    "viewImport.notesActivityType": "必填。填写 支出、收入、转账、投资。信用卡还款也填写 转账，系统按账户方向识别，不需要在分类里写信用卡还款。",
    "viewImport.notesAmount": "必填。统一填正数；方向优先看“流出/流入”，未填写时再按收支大类推断。",
    "viewImport.notesOutflow": "选填。账户侧资金减少时填写，例如消费、转出、取现。",
    "viewImport.notesInflow": "选填。账户侧资金增加时填写，例如收入、信用卡还款、退款、退货、冲正。",
    "viewImport.notesAccount": "必填。支出/收入写发生账户；转账可写当前视角账户；信用卡账单页导入时可统一写当前信用卡账户。",
    "viewImport.notesCounterAccount": "仅转账时填写另一侧账户。信用卡还款若账户列是信用卡，这里写付款账户；若账户列是付款账户，这里写信用卡账户。非转账记录填写后只会预览警告并忽略。",
    "viewImport.notesCategory": "选填。填写账簿中已有分类名称，系统会按现有分类/学习规则对齐。",
    "viewImport.notesCounterparty": "选填。填写商户、银行、支付机构等明确机构名。",
    "viewImport.notesTags": "选填。多个标签按现有导入规则处理。",
    "viewImport.notesRemark": "选填。自由文本备注，放在最后一列。",
    "viewImport.notesIntroFund": "模板页第 1 行是稳定字段键名，第 2 行是中文显示名称；导入时按字段键名识别。备注字段固定放在最后。",
    "viewImport.notesRecognitionFund": "系统只识别有明确表头和业务方向的字段；不能确定含义时会在预览里报错或警告，不会强行改作其他字段。",
    "viewImport.notesFundSubtype": "必填。填写 buy、redeem、dividend_cash、dividend_reinvest、refund。",
