    "batchImport.guideTitle": "Import Guide",
    "batchImport.guide.currentSupport": "This entry now supports CSV, XLSX, and XLS upload plus preview confirmation and import for both the regular bill template and the fund template. Credit card statement records have been merged into the regular bill template, with preview validation for credit card accounts, posting dates, and repayment transfers.",
    "batchImport.guide.fundSubtypeSource": "In the fund template, `fundSubtype` and `source` are explicit fields rather than inferred from notes. During preview, the system fills stored confirm days, confirm date, and fee without issuing extra NAV queries. When a regular investment succeeds for part of the amount and refunds the rest, prefer one `buy + regular_invest` row and one `refund + regular_invest_refund` row.",
    "batchImport.guide.normalBill": "Bill records are imported by the Chinese contract headers. The template columns map directly to storage semantics: `收支大类` controls the record type, `金额` maps to amount, `流出/流入` takes priority for account-side direction, `分类` maps to category, `标签` maps to tag relations, and `备注` maps to note. `流出/流入` are recommended, not required; files with only `金额` fall back to amount sign, major type, and repayment/refund keywords. For transfers, `账户` may be the current-side account and `对向账户` is the other side; credit-card repayments are also transfers and may put the credit card in `账户` with the repayment amount in `流入`. Older files using `类型/原始类型` or legacy credit-card columns such as `cardAccount/type/merchant` are still recognized.",
    "batchImport.previewTitle": "Import Preview",
