    "batchImport.template.normal.title": "Bill Import",
    "batchImport.template.normal.description": "Use one upload entry for regular bills and credit-card statements. The file is classified during parsing; regular bills resolve accounts per row, while card statements share one card and resolve repayment sources separately.",
    "batchImport.template.normal.status": "Ready for upload and import",
    "batchImport.template.normal.field.date": "Writes the transaction date in YYYY-MM-DD format to the `date` field.",
    "batchImport.template.normal.field.postedAt": "Optional actual posting date for expense records, using YYYY-MM-DD, written to `postedAt`. Empty values default to the transaction date.",
    "batchImport.template.normal.field.majorType": "Writes the major record type to `type`; use Expense/Income/Transfer/Investment or the localized equivalents. Credit-card repayments should use Transfer; the system recognizes repayment from account direction.",
    "batchImport.template.normal.field.amount": "Writes the record amount to `amount`. The template recommends positive numbers plus `outflow` / `inflow`; files with only an amount column are still inferred from amount sign, major type, and repayment/refund keywords.",
    "batchImport.template.normal.field.outflow": "Fill when the account-side cash decreases, such as spending, transfer-out, or cash withdrawal.",
    "batchImport.template.normal.field.inflow": "Fill when the account-side cash increases, such as income, credit-card repayment, refund, return, or reversal.",
    "batchImport.template.normal.field.account": "Main account field. For expense/income, use the posting account. For transfers, use the current-side account. Credit-card spending, refunds, and repayments may all use the credit-card account here, with direction expressed by inflow/outflow.",
    "batchImport.template.normal.field.counterAccount": "The other side of a transfer. For credit-card repayment, put the paying account here when the account column is the credit card; put the credit card here when the account column is the paying account.",
    "batchImport.template.normal.field.category": "Category field. Recommended for expenses and income, such as dining, interest income, interest expense, or salary.",
    "batchImport.template.normal.field.institution": "Income/expense institution, limited to banks or third-party payment providers.",
    "batchImport.template.normal.field.tags": "Tag relations. Multiple tags can be separated with Chinese or English commas.",
    "batchImport.template.normal.field.remark": "Main note written to `note`.",
    "batchImport.template.fund.title": "Fund Record Template",
    "batchImport.template.fund.description": "For fund buy, sell, dividend, refund, fee, NAV, and unit details. The preview auto-fills NAV, fee, units, and confirmation date. Cash account, fund account, `fundSubtype`, and `source` should still be distinguished explicitly.",
    "batchImport.template.pending": "Template provided; dedicated import flow pending",
    "batchImport.template.fund.field.date": "Trade date in YYYY-MM-DD format.",
    "batchImport.template.fund.field.fundSubtype": "Fund action. Common values: buy, redeem, dividend_cash, dividend_reinvest, refund (cash returned; imported as the refund record subtype).",
    "batchImport.template.fund.field.source": "Source semantics. Common values: manual, regular_invest, regular_invest_refund. If a regular investment of 200 succeeds for 100 and refunds 100, split it into one buy + regular_invest row and one refund + regular_invest_refund row.",
    "batchImport.template.fund.field.cashAccount": "Name of the cash account. Recommended whenever the record has a cash leg, such as buy, recurring buy, refund, or redemption settlement.",
    "batchImport.template.fund.field.fundAccount": "Name of the fund account. This is required to distinguish multiple fund accounts and should not be inferred from fund code alone.",
    "batchImport.template.fund.field.fundCode": "Fund code used later for NAV and position linkage.",
    "batchImport.template.fund.field.fundName": "Fund name, optional for display completion.",
    "batchImport.template.fund.field.amount": "Transaction amount. Use a positive number; direction is determined by `fundSubtype`, not by the sign.",
    "batchImport.template.fund.field.units": "Confirmed units. Recommended for buy and redeem; usually blank for refund rows.",
    "batchImport.template.fund.field.nav": "Executed NAV. Recommended for buy and redeem; usually blank for refund rows.",
    "batchImport.template.fund.field.fee": "Fee amount. Leave blank if none.",
    "batchImport.template.fund.field.confirmDate": "NAV date. If omitted, the system may derive it from stored confirm-day settings.",
    "batchImport.template.fund.field.arrivalDate": "Posting date. If omitted, the system may derive it from stored arrival-day settings for later P/L views.",
