    "liabilitiesGuide.newDebtTransaction": "New Transaction",
    "liabilitiesGuide.guideTitle": "How to Create a Transaction",
    "liabilitiesGuide.selectedHint": "Currently selected: {name}. After clicking \"New Transaction\" at the top right, the \"Counterparty\" field in the dialog will default to it; you can also switch or add a counterparty inside the dialog.",
    "liabilitiesGuide.noSelectionHint": "Add a counterparty on the left first. Without a counterparty, the \"New Transaction\" button is hidden so no unowned receivable/payable account is created.",
    "liabilitiesGuide.step1Title": "1. Choose the operation type",
    "liabilitiesGuide.step1Text": "Borrowing means the other party gives you money; lending means you give them money; repayment and collection reduce existing balances.",
    "liabilitiesGuide.step2Title": "2. Choose the cash account",
    "liabilitiesGuide.step2Text": "The cash account is the cash, debit card, e-wallet, or credit card side that records where money actually flows in or out.",
    "liabilitiesGuide.step3Title": "3. Choose the counterparty",
    "liabilitiesGuide.step3Text": "Ordinary transactions require a counterparty. If none exists, add one from the left list or directly from the counterparty dropdown in the dialog.",
    "liabilitiesGuide.step4Title": "4. Confirm the receivable/payable account",
    "liabilitiesGuide.step4Text": "People/organizations usually reuse the same receivable/payable account under that counterparty; if no account is chosen, saving will automatically reuse or create \"XXX's receivable/payable\".",
    "liabilitiesGuide.step5Title": "5. Enter the amount and note",
    "liabilitiesGuide.step5Text": "Principal forms or reduces the receivable/payable balance; interest is only needed for repayment or collection. The note explains the reason, such as short-term cash flow or paying for a meal on someone's behalf.",
    "liabilitiesGuide.suggestedOrderTitle": "Recommended Order",
    "liabilitiesGuide.suggestedOrderText": "For beginners, create the \"person/company\" first, then record the first borrowing or lending; for later repayments, collections, or reimbursement of paid-on-behalf amounts, keep selecting the same counterparty so the balance settles naturally.",
