    "viewImport.notesIntroLabel": "Note",
    "viewImport.notesRecognitionLabel": "Recognition Principle",
    "viewImport.notesIntroNormal": "Row 1 of the template page contains stable field keys; import recognizes fields by these keys. The remark field is always the last column.",
    "viewImport.notesRecognitionNormal": "The system only recognizes fields with clear headers and income/expense direction; when a field's meaning cannot be determined, the preview shows an error or warning instead of forcing the field to another use.",
    "viewImport.notesDate": "Required. Enter the transaction date, preferably YYYY-MM-DD; common Excel date formats are also accepted.",
    "viewImport.notesPostedAt": "Optional. Expense records may include the actual posting date; if it cannot be recognized, the preview warns and treats it as empty.",
    "viewImport.notesActivityType": "Required. Enter Expense, Income, Transfer, or Investment. Credit card repayment is also entered as Transfer; the system infers direction from the accounts, so you do not need to write credit card repayment in the category.",
    "viewImport.notesAmount": "Required. Enter positive numbers only; direction is taken from the Outflow/Inflow columns first, then inferred from the activity type when they are empty.",
    "viewImport.notesOutflow": "Optional. Fill in when funds decrease on the account side, e.g. spending, transfers out, cash withdrawals.",
    "viewImport.notesInflow": "Optional. Fill in when funds increase on the account side, e.g. income, credit card repayment, refunds, returns, reversals.",
    "viewImport.notesAccount": "Required. Expense/income records use the account where they occurred; transfers may use the current view account; when importing on a credit card bill page, you may uniformly use the current credit card account.",
    "viewImport.notesCounterAccount": "Only fill in the other-side account for transfers. For credit card repayment, if the account column holds the credit card, enter the payment account here; if it holds the payment account, enter the credit card account here. On non-transfer records this only triggers a preview warning and is ignored.",
    "viewImport.notesCategory": "Optional. Enter an existing category name in the book; the system aligns it using the existing category/learning rules.",
    "viewImport.notesCounterparty": "Optional. Enter a clear institution name such as a merchant, bank, or payment provider.",
    "viewImport.notesTags": "Optional. Multiple tags are handled according to the existing import rules.",
    "viewImport.notesRemark": "Optional. Free-text remark, placed in the last column.",
    "viewImport.notesIntroFund": "Row 1 of the template page contains stable field keys and row 2 shows display names; import recognizes fields by the field keys. The remark field is always the last column.",
    "viewImport.notesRecognitionFund": "The system only recognizes fields with clear headers and business direction; when a field's meaning cannot be determined, the preview shows an error or warning rather than forcing the field to another use.",
    "viewImport.notesFundSubtype": "Required. Enter buy, redeem, dividend_cash, dividend_reinvest, or refund.",
    "viewImport.notesSource": "Optional. Enter a source such as manual, regular_invest, or regular_invest_refund; leave empty to treat as a manual import.",
    "viewImport.notesCashAccount": "Fill in the cash account when cash flows in or out; when left empty, the fund import rules validate it.",
    "viewImport.notesFundAccount": "Required. The fund account; this template defaults to the current view account.",
    "viewImport.notesFundCode": "Required. The fund code is the identity key for fund records; the fund name is for display only.",
    "viewImport.notesFundAmount": "Required. Enter a positive number; the direction is determined by fundSubtype.",
    "viewImport.notesUnitsNavFee": "Optional. Units, NAV, and fees go through fund preview validation; when missing, they are completed or prompted per the existing fund rules.",
    "viewImport.notesConfirmArrival": "Optional. They represent the confirmation/NAV date and the cash posting date respectively.",
