    "batchImport.required": "必須",
    "batchImport.optional": "任意",
    "batchImport.guideTitle": "インポート案内",
    "batchImport.guide.currentSupport": "この画面では現在、「帳票記録テンプレート」と「基金記録テンプレート」の CSV、XLSX、XLS のアップロード、プレビュー確認、取り込みに対応しています。クレジットカード明細記録は「帳票記録テンプレート」に統合され、カード口座、入帳日、返済振替ルールでプレビュー検証します。",
    "batchImport.guide.fundSubtypeSource": "基金テンプレートでは `fundSubtype` と `source` を備考から推測せず、明示項目として扱います。プレビューでは一致した基金口座の設定から確認日数、確認日、手数料を補完し、プレビューのために追加の基準価額照会は行いません。積立 200 のうち 100 だけ成立して 100 が返金された場合は、`buy + regular_invest` と `refund + regular_invest_refund` の 2 行に分けてください。",
    "batchImport.guide.normalBill": "帳票記録は中国語の契約ヘッダーで取り込みます。テンプレート列は保存先の意味に対応し、`收支大类` は記録種別、`金额` は金額、`流出/流入` は口座側の方向を優先的に表し、`分类` はカテゴリ、`标签` はタグ関連、`备注` は備考に対応します。`流出/流入` は推奨列で必須ではありません。`金额` だけのファイルは金額の符号、記録種別、返済/返金キーワードで推定します。振替では `账户` を現在側の口座、`对向账户` をもう一方の口座として入力できます。カード返済も振替で、カードを `账户` に置き返済額を `流入` に入力できます。旧ファイルの `类型/原始类型` や旧カード明細テンプレートの `cardAccount/type/merchant` 列も引き続き認識します。",
