    "batchImport.template.normal.title": "帳票インポート",
    "batchImport.template.normal.description": "通常明細とクレジットカード明細を1つの入口から読み込み、解析時にモードを自動判定します。通常明細は行ごとに口座を識別し、カード明細はカードを統一して返済元だけを個別に識別します。",
    "batchImport.template.normal.status": "アップロードして取り込み可能",
    "batchImport.template.normal.field.date": "取引日を YYYY-MM-DD 形式で `date` に書き込みます。",
    "batchImport.template.normal.field.postedAt": "支出記録の実際の入帳日です。YYYY-MM-DD 形式で `postedAt` に書き込みます。空欄は取引日扱いです。",
    "batchImport.template.normal.field.majorType": "記録の大類を `type` に書き込みます。支出、収入、振替、投資を使用します。クレジットカード返済は振替として入力し、システムが口座方向から返済として識別します。",
    "batchImport.template.normal.field.amount": "`amount` に記録金額を書き込みます。テンプレートでは正数と `outflow` / `inflow` の利用を推奨しますが、金額列だけのファイルも金額の符号、記録種別、返済/返金キーワードから推定します。",
    "batchImport.template.normal.field.outflow": "口座側の資金が減る場合に入力します。例: 消費、振替出金、現金引き出し。",
    "batchImport.template.normal.field.inflow": "口座側の資金が増える場合に入力します。例: 収入、クレジットカード返済、返金、返品、取消。",
    "batchImport.template.normal.field.account": "主口座。支出・収入は発生口座、振替は現在見ている側の口座を使えます。クレジットカードの利用・返金・返済はカード口座を入力し、流入/流出で方向を表せます。",
    "batchImport.template.normal.field.counterAccount": "振替のもう一方の口座です。カード返済で口座列がカードならここに支払口座を、口座列が支払口座ならここにカード口座を入力します。",
    "batchImport.template.normal.field.category": "カテゴリ項目。支出・収入では、食事、利息収入、利息支出、給与などの入力を推奨します。",
    "batchImport.template.normal.field.institution": "収支機関。銀行または第三者決済機関に限定します。",
    "batchImport.template.normal.field.tags": "タグ関連。複数タグは中国語または英語のカンマで区切れます。",
    "batchImport.template.normal.field.remark": "主備考。`note` に書き込みます。",
    "batchImport.template.fund.title": "基金記録テンプレート",
    "batchImport.template.fund.description": "基金の購入、売却、配当、返金、手数料、基準価額、口数明細に使用します。プレビューで基準価額、手数料、口数、確認日を自動補完します。資金口座、基金口座、`fundSubtype`、`source` は明確に分けて入力してください。",
    "batchImport.template.pending": "テンプレート提供済み、専用取込フロー待ち",
