    "batchImport.template.fund.field.fundSubtype": "基金アクション。代表値: buy、redeem、dividend_cash、dividend_reinvest、refund（資金返金、取込時は返金記録として扱います）。",
    "batchImport.template.fund.field.source": "発生元の意味。代表値: manual、regular_invest、regular_invest_refund。積立 200 のうち 100 が成立し 100 が返金された場合は、buy + regular_invest と refund + regular_invest_refund に分けます。",
    "batchImport.template.fund.field.cashAccount": "資金口座名。購入、積立購入、返金、解約入金など、現金の出入りがある記録では入力を推奨します。",
