    "firstUseGuide.step.family.why2": "デフォルトメンバーに台帳名を使い続けると、台帳名とユーザー/メンバーが混ざり、以降の選択が不明確になります。",
    "firstUseGuide.step.family.action0": "デフォルトメンバー「{name}」を実際の氏名または安定した略称に変更してください。",
