    "firstUseGuide.step.insurance.intro": "保険口座は保険証券、保険料、解約返戻金、保障対象を記録します。普通の銀行カードと違い、保険証券の帰属と長期的なキャッシュフローが重要です。",
    "firstUseGuide.step.insurance.why0": "保険証券は通常何年にもわたり、保険料、更新、解約、解約返戻金を個別に追跡する必要があります。",
    "firstUseGuide.step.insurance.why1": "保険は特定のメンバーに属し、世帯の総資産、負債、保障状況に関わります。",
    "firstUseGuide.step.insurance.why2": "保険を独立したモジュールに置くことで、日常の支出一覧がすっきりします。",
    "firstUseGuide.step.insurance.action0": "保険証券がある場合は、先に保険口座または保険商品を追加し、次に所属メンバーを追加してください。",
    "firstUseGuide.step.insurance.action1": "保険料、支払頻度、解約返戻金など後で確認する項目を入力してください。",
    "firstUseGuide.step.insurance.action2": "保険証券がない場合やまだ管理したくない場合は、未完了のままでも日常の記帳に影響しません。",
    "firstUseGuide.step.insurance.done0": "保険口座数：{count}。",
    "firstUseGuide.step.insurance.done1": "主要な保険証券がメンバーと商品に対応付けられていること。",
    "firstUseGuide.step.insurance.done2": "次の保険料や支払いが発生したとき、どの保険口座に記帳すべきか分かること。",
    "firstUseGuide.step.insurance.tip0": "このステップは任意です。",
    "firstUseGuide.step.insurance.tip1": "保障情報と解約返戻金は分けて管理するのが良いです。",
    "firstUseGuide.step.insurance.tip2": "先に主契約を入力し、特約は後から追加できます。",
    "firstUseGuide.step.settlements.detailDone": "立替・貸借口座 {count} 件",
    "firstUseGuide.step.settlements.detailTodo": "借入、貸出、立替先を追加",
    "firstUseGuide.step.settlements.action": "立替・貸借を開く",
    "firstUseGuide.step.settlements.intro": "立替・貸借は借入、貸出、立替払い、未精算を記録します。初心者の段階では、まず相手先（人/組織）を作成し、その相手先で最初の立替・貸借を記録してください。",
    "firstUseGuide.step.settlements.why0": "親族・知人からの借入、会社の立替、代理購入・代理支払いは、いずれも相手先と残高を保持する必要があります。",
    "firstUseGuide.step.settlements.why1": "立替・貸借を普通の収入/支出として記帳すると、後で精算済みかどうか確認しづらくなります。",
    "firstUseGuide.step.settlements.why2": "相手先を明確にしておけば、回収、返済、相殺を同じ関係の中で記録できます。",
    "firstUseGuide.step.settlements.action0": "先に左側の相手先一覧で対象を新規作成または選択してください。",
    "firstUseGuide.step.settlements.action1": "対象ができたら、「新規立替・貸借」をクリックし、借入、貸出、返済、回収を選択してください。",
    "firstUseGuide.step.settlements.action2": "相手先がない場合は、ガイド画面またはダイアログのドロップダウンで直接作成できます。",
    "firstUseGuide.step.settlements.done0": "立替・貸借口座数：{count}。",
    "firstUseGuide.step.settlements.done1": "未精算の各対象で、未収または未払いの残高を確認できること。",
    "firstUseGuide.step.settlements.done2": "その後の返済/回収で同じ対象を選択して記録を続けられること。",
    "firstUseGuide.step.settlements.tip0": "このステップは任意です。",
    "firstUseGuide.step.settlements.tip1": "借入元本を収入として扱わないでください。",
    "firstUseGuide.step.settlements.tip2": "回収した貸付金を普通の収入として扱わないでください。",
    "firstUseGuide.step.daily.title": "日常記帳",
    "firstUseGuide.step.daily.detailDone": "日常取引 {count} 件",
    "firstUseGuide.step.daily.detailTodo": "{account} の資金明細を開く",
    "firstUseGuide.step.daily.actionDetail": "資金明細を開く",
    "firstUseGuide.step.daily.actionWorkspace": "ワークスペースへ",
    "firstUseGuide.step.daily.intro": "日常記帳は {account} の資金明細表から始めます。表は取引日順に表示されるので、タイプ、分類、相手口座、入金/出金、残高が実際の資金の流れと一致しているかを重点的に確認してください。",
    "firstUseGuide.step.daily.why0": "日常取引は口座残高、分類統計、クレジットカード請求、資産変動に影響します。",
    "firstUseGuide.step.daily.why1": "口座の起点が不明確だと、以降の取引すべてが残高修正のパッチになります。",
    "firstUseGuide.step.daily.why2": "請求書のインポートとAI認識は、既存の口座、金融機関、分類、過去のメモに基づいて自動判断します。",
    "firstUseGuide.step.daily.action0": "直近の実際の取引から入力し、口座、方向、分類の正確さを優先してください。",
    "firstUseGuide.step.daily.action1": "クレジットカードの返済、口座間の振替、チャージ・出金はまず振替として認識してください。",
    "firstUseGuide.step.daily.actionPlanDone": "計画タスクが {count} 件あります。実行口座を引き続き確認できます。",
    "firstUseGuide.step.daily.actionPlanTodo": "定期積立、保険料、家賃、固定引落は後で計画タスクで管理できます。",
    "firstUseGuide.step.daily.done0": "日常取引数：{count}。",
    "firstUseGuide.step.daily.done1": "最初の取引を保存した後、口座残高と統計に明らかな方向の誤りがないこと。",
    "firstUseGuide.step.daily.done2": "よくあるメモが徐々に認識ルールになり、今後のインポートが楽になります。",
    "firstUseGuide.step.daily.tip0": "まず入金/出金の方向を確認し、その後に分類を細かく設定してください。",
    "firstUseGuide.step.daily.tip1": "残高は期首残高と順序のある取引から導かれます。",
    "firstUseGuide.step.daily.tip2": "一括インポート後は、口座と方向を重点的に確認してください。",
