    "viewImport.notesIntroNormal": "テンプレートの1行目は安定したフィールドキー名です。取り込み時はフィールドキー名で認識します。備考フィールドは常に最後の列です。",
    "viewImport.notesRecognitionNormal": "システムは明確なヘッダーと収支方向を持つフィールドのみを認識します。意味を判断できない場合は、プレビューでエラーまたは警告を表示し、フィールドを別の用途に無理に変更することはありません。",
    "viewImport.notesDate": "必須。取引日を入力します。YYYY-MM-DD を推奨します。一般的な Excel の日付形式にも対応します。",
    "viewImport.notesPostedAt": "任意。支出記録には実際の入金日を入力できます。認識できない場合はプレビューで警告し、空値として扱います。",
    "viewImport.notesActivityType": "必須。支出、収入、振替、投資のいずれかを入力します。クレジットカード返済も「振替」で入力します。システムが口座の方向で認識するため、カテゴリにクレジットカード返済と書く必要はありません。",
    "viewImport.notesAmount": "必須。正の数で統一して入力します。方向は「流出/流入」列を優先し、未入力の場合は収支区分から推測します。",
    "viewImport.notesOutflow": "任意。口座側の資金が減少する場合に入力します。例：消費、振替出金、現金引き出し。",
    "viewImport.notesInflow": "任意。口座側の資金が増加する場合に入力します。例：収入、クレジットカード返済、返金、返品、訂正。",
    "viewImport.notesAccount": "必須。支出/収入は発生した口座を入力します。振替は現在のビュー口座で可。クレジットカード明細ページでの取り込み時は現在のクレジットカード口座で統一できます。",
    "viewImport.notesCounterAccount": "振替時のみ反対側の口座を入力します。クレジットカード返済の場合、口座列がクレジットカードなら支払い口座を、支払い口座ならクレジットカード口座を入力します。振替以外の記録ではプレビュー警告のみで無視されます。",
    "viewImport.notesCategory": "任意。帳簿に既存のカテゴリ名を入力します。システムは既存のカテゴリ/学習ルールに合わせます。",
    "viewImport.notesCounterparty": "任意。加盟店、銀行、決済機関など明確な機関名を入力します。",
    "viewImport.notesTags": "任意。複数のタグは既存の取り込みルールに従って処理されます。",
    "viewImport.notesRemark": "任意。自由文の備考で、最後の列に置きます。",
    "viewImport.notesIntroFund": "テンプレートの1行目は安定したフィールドキー名、2行目は表示名です。取り込み時はフィールドキー名で認識します。備考フィールドは常に最後の列です。",
    "viewImport.notesRecognitionFund": "システムは明確なヘッダーと業務方向を持つフィールドのみを認識します。意味を判断できない場合はプレビューでエラーまたは警告を表示し、無理に別のフィールドに変更しません。",
    "viewImport.notesFundSubtype": "必須。buy、redeem、dividend_cash、dividend_reinvest、refund のいずれかを入力します。",
