export type I18nKey = keyof typeof I18N_MESSAGES["zh-CN"];

export function translate(language: DisplayLanguage, key: string, params?: Record<string, string | number>) {
  const typedKey = key as I18nKey;
  const template = I18N_MESSAGES[language]?.[typedKey] ?? I18N_MESSAGES["zh-CN"][typedKey] ?? key;
  if (!params) return template;
  return template.replace(/\{(\w+)\}/g, (match, name) => (name in params ? String(params[name]) : match));
}

